package org.slavicmyths.client;
import net.minecraft.client.model.geom.ModelPart;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
/** Loads only native mesh builders; no Minecraft bootstrap, world, client, window or renderer. */
public final class UndergroundModelChecks {
 static int checks;static void check(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}
 static java.lang.reflect.Field cubes,children,polygons;
 static JsonArray export(ModelPart p,String name,float x,float y,float z) throws Exception {x+=p.x;y+=p.y;z+=p.z;var result=new JsonArray();for(Object raw:(List<?>)cubes.get(p)){var cube=(ModelPart.Cube)raw;check(cube.maxX>cube.minX&&cube.maxY>cube.minY&&cube.maxZ>cube.minZ,"positive cube "+name);var c=new JsonObject();c.addProperty("part",name);c.add("min",new Gson().toJsonTree(new float[]{x+cube.minX,y+cube.minY,z+cube.minZ}));c.add("max",new Gson().toJsonTree(new float[]{x+cube.maxX,y+cube.maxY,z+cube.maxZ}));
 var faces=new JsonArray();for(Object rawFace:(Object[])polygons.get(cube)){if(rawFace==null)continue;var field=rawFace.getClass().getDeclaredField("vertices");field.setAccessible(true);Object[] vertices=(Object[])field.get(rawFace);var face=new JsonArray();for(Object vertex:vertices){var v=vertex.getClass();var u=v.getDeclaredField("u");var uv=v.getDeclaredField("v");var pos=v.getDeclaredField("pos");u.setAccessible(true);uv.setAccessible(true);pos.setAccessible(true);float a=u.getFloat(vertex),b=uv.getFloat(vertex);check(a>=0&&a<=1&&b>=0&&b<=1,"UV within128 "+name+" "+a+","+b);var point=(org.joml.Vector3f)pos.get(vertex);face.add(new Gson().toJsonTree(new float[]{x+point.x,y+point.y,z+point.z,a,b}));}faces.add(face);}c.add("faces",faces);result.add(c);}
 for(var child:((Map<String,ModelPart>)children.get(p)).entrySet()){var extra=export(child.getValue(),name+"/"+child.getKey(),x,y,z);for(var c:extra)result.add(c);}return result;}
 public static void main(String[] args) throws Exception {UndergroundRuleChecks.run();UndergroundSaveChecks.run();cubes=ModelPart.class.getDeclaredField("cubes");children=ModelPart.class.getDeclaredField("children");polygons=ModelPart.Cube.class.getDeclaredField("polygons");cubes.setAccessible(true);children.setAccessible(true);polygons.setAccessible(true);var models=new JsonObject();String[] names={"podzemnik","podzemnik_miner","kladovik","large_podzemnik"};for(int i=0;i<4;i++){var root=UndergroundClient.Model.mesh(i);var geometry=export(root,names[i],0,0,0);check(geometry.size()>=16,"articulated model");check(root.getChild("body").getChild("right_arm").hasChild("forearm")&&root.getChild("body").getChild("head").hasChild("jaw"),"separate articulated joints");float minY=100,maxY=-100;for(var box:geometry){String part=box.getAsJsonObject().get("part").getAsString();if(part.contains("held_stone"))continue;minY=Math.min(minY,box.getAsJsonObject().getAsJsonArray("min").get(1).getAsFloat());maxY=Math.max(maxY,box.getAsJsonObject().getAsJsonArray("max").get(1).getAsFloat());}float height=(maxY-minY)/16*(i==0?.825F:i==1?.88F:1);check(i==3?height>=2.7F&&height<=3: i==2?height>=1.35F&&height<=1.5F:i==1?height>=1.75F&&height<=1.85F:height>=1.6F&&height<=1.7F,"physical silhouette height "+height);models.add(names[i],geometry);System.out.println(names[i]+": boxes="+geometry.size()+", model height="+height);}
 var out=Path.of("work/mobs/model-meshes.json");Files.createDirectories(out.getParent());Files.writeString(out,new GsonBuilder().setPrettyPrinting().create().toJson(models));System.out.println("MESH PASS: "+checks+" assertions; zero Minecraft launches");}
}
